sys_script_include.script:
var EventRepository = Class.create();
EventRepository.prototype = {

    TABLE: 'x_1044869_tomek_0_event_cache',

    tryCreate: function(payload) {

        try {
            var gr = new GlideRecord(this.TABLE);
            gr.initialize();

            gr.u_trello_action_id = payload.u_trello_action_id;
            gr.u_trello_card_id = payload.u_trello_card_id;
            gr.u_processing_status = 'Processing';
            gr.u_event_type_translation_key = payload.u_event_type_translation_key;
            gr.u_event_date = payload.u_event_date;
            gr.u_source = payload.u_source;
            gr.u_error_message = "";

            return gr.insert();

        } catch (err) {
            return null; // duplicate
        }
    },

    markProcessed: function(eventId) {

        var gr = new GlideRecord(this.TABLE);
        if (gr.get(eventId)) {
            gr.u_processing_status = 'Processed';
            gr.u_processed_at = new GlideDateTime();
            gr.update();
        }
    },

    markFailed: function(eventId, errorMessage) {

        var gr = new GlideRecord(this.TABLE);
        if (gr.get(eventId)) {
            gr.u_processing_status = 'Failed';
            gr.u_error_message = errorMessage;
            gr.update();
        }
    },

    type: 'EventRepository'
};
